-- Runs a CLI built by clingy.build. Loads only what parsing and running
-- need: no DSL, compiler, help or completion code until they are used, and
-- no schema reflection, since inspections were computed at build time.
--
--   local runtime = require("clingy.runtime")
--   os.exit(runtime.run(require("greet.built"), arg))

local M = {}

M.FORMAT = "clingy.built.v1"

---Checks the format and returns a compiled router for `built`.
---@param built table A module generated by clingy.build.
---@return table router
function M.load(built)
  if type(built) ~= "table" or built.format ~= M.FORMAT then
    error(("clingy.runtime: expected a %s module, got %s"):format(M.FORMAT,
      type(built) == "table" and tostring(built.format) or type(built)), 2)
  end
  local adapter = require("clingy.adapter")
  for _, entry in ipairs(built.schemas or {}) do
    adapter.preload_inspection(entry.schema, entry.info)
  end
  local router = require("clingy.router").compile(built.graph)
  router.root.graph = built.graph
  return router
end

---Creates an app from a built CLI.
---@param built table
---@param config? { mode?: string, presentation?: table } Runtime options, as for c.create.
---@return table app
function M.create(built, config)
  return require("clingy.app").create_app(M.load(built), config or {})
end

---Runs a built CLI with `argv` and returns its exit code.
---@param built table
---@param argv string[]
---@param config? table
---@return integer
function M.run(built, argv, config)
  return M.create(built, config):run(argv)
end

return M
